import{_ as e,o as t,c as i,a2 as l}from"./chunks/framework.CdjpmwdR.js";const d=JSON.parse('{"title":"Mesh-Shaped PKM：Logseq 个人知识管理体系","description":"本文拆解我在 Logseq 上落地 PKM 的完整流程：输入采集、任务循环、笔记沉淀与输出反馈，目标是把“记录行为”转成可持续的能力增长。","frontmatter":{"category":"domain","date":"2022-12-01","title":"Mesh-Shaped PKM：Logseq 个人知识管理体系","description":"本文拆解我在 Logseq 上落地 PKM 的完整流程：输入采集、任务循环、笔记沉淀与输出反馈，目标是把“记录行为”转成可持续的能力增长。","tags":["domain","PKM","logseq"],"image":"https://pic3.zhimg.com/v2-e53cc5d58b612b5154574f0eb2110d72_r.jpg"},"headers":[],"relativePath":"blogs/2022/202212-logseq-pkm.md","filePath":"blogs/2022/202212-logseq-pkm.md"}'),o={name:"blogs/2022/202212-logseq-pkm.md"};function r(h,a,p,s,n,u){return t(),i("div",null,[...a[0]||(a[0]=[l('<p><img src="https://pic3.zhimg.com/v2-e53cc5d58b612b5154574f0eb2110d72_r.jpg" alt=""> 在年初写下 <a href="https://zhuanlan.zhihu.com/p/575842220" target="_blank" rel="noreferrer">&quot;Mesh-Shaped&quot; - 如何成长为云原生开发者</a> 之后，我一直在迭代自己的知识管理系统：</p><blockquote><p>知识管理方式会反映你的思维路径，而思维路径决定输出质量。</p></blockquote><p>目前这套工作流已经稳定运行一段时间，涉及工具、方法论和协作习惯。本文用图解方式把它拆开，方便你按模块复用。</p><h2 id="输入-input" tabindex="-1">输入 Input <a class="header-anchor" href="#输入-input" aria-label="Permalink to &quot;输入 Input&quot;">​</a></h2><p><img src="https://pic4.zhimg.com/80/v2-0a99df5b67b41531e39dd8f9c5e7bb23_1440w.webp" alt=""></p><h3 id="方法论" tabindex="-1">方法论 <a class="header-anchor" href="#方法论" aria-label="Permalink to &quot;方法论&quot;">​</a></h3><ul><li><a href="https://link.zhihu.com/?target=https%3A//book.douban.com/subject/35503571/" target="_blank" rel="noreferrer">卡片笔记学习法</a></li><li>OKR</li><li>逻辑树</li></ul><h3 id="输入源" tabindex="-1">输入源 <a class="header-anchor" href="#输入源" aria-label="Permalink to &quot;输入源&quot;">​</a></h3><ul><li>任务输入：有较明确的目标的任务，需要在一定时间点完成，并产生相应产物的（<a href="https://link.zhihu.com/?target=https%3A//baike.baidu.com/item/SMART%25E5%258E%259F%25E5%2588%2599/8575850" target="_blank" rel="noreferrer">SMART 原则</a>）</li><li>知识输入：学习某一块知识所随机产生的研究、探索、阅读，通常伴随着各种附件，书、文献、图片或 ppt</li></ul><h3 id="工具" tabindex="-1">工具 <a class="header-anchor" href="#工具" aria-label="Permalink to &quot;工具&quot;">​</a></h3><ul><li><p>GoFullPage：Chrome 插件，用于截屏</p></li><li><p>MarkDownload：Chrome 插件，可以将网页或选段“下载/保存为 Markdown 格式”，方便加入 Logseq</p></li><li><p>Cubox：Chrome/iOS/Wechat 多端插件，作为一个媒体库保存任意内容</p></li><li><p><em>Cubox 功能很强大，如果 收集&gt;产出 的话，只使用 Cubox 也是不错的选择</em></p></li><li><p><em>我是将 Cubox 作为收集工具使用的，比如看到一篇公众号文章、看到一篇知乎，都可以先通过 Cubox 暂存，再通过 GTD（Logseq）来消费这些“内容”</em></p></li></ul><h3 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h3><ul><li><p>Logseq：将 Logseq 的功能 和 卡片笔记学习法 相结合，分离出不同的页面来管理不同的内容</p></li><li><p>Journey，即 Logseq 每天自动生成的页面，来记录一些琐碎的内容，任务使用 &quot;TODO&quot; 标签进行管理</p></li><li><p>Note，就是正常的 Page</p></li><li><p>Project，也是正常的 Page，会添加一些前缀来标识某一个项目</p></li><li><p>OKR，其实也是一个正常的 Page，会通过 tag/hierarchy/query 功能来进一步追踪和管理</p></li></ul><p><img src="https://pic3.zhimg.com/80/v2-d99183cdf27244b27bf6499e9b3f6e6e_1440w.webp" alt="OKR Hierarchy"></p><h2 id="知识循环-iteration" tabindex="-1">知识循环 Iteration <a class="header-anchor" href="#知识循环-iteration" aria-label="Permalink to &quot;知识循环 Iteration&quot;">​</a></h2><p><img src="https://pic1.zhimg.com/80/v2-28beb58c07769b2e95fb85572e6ba290_1440w.webp" alt="iteration"></p><h3 id="方法论-1" tabindex="-1">方法论 <a class="header-anchor" href="#方法论-1" aria-label="Permalink to &quot;方法论&quot;">​</a></h3><ul><li>OKR</li><li>GTD（Get things done）</li><li>Mesh-Shaped：<a href="https://zhuanlan.zhihu.com/p/575842220" target="_blank" rel="noreferrer">Anddd7：&quot;Mesh-Shaped&quot; - 如何成长为云原生开发者</a></li></ul><h3 id="任务区" tabindex="-1">任务区 <a class="header-anchor" href="#任务区" aria-label="Permalink to &quot;任务区&quot;">​</a></h3><ul><li><p>OKR：（同上）</p></li><li><p>Roadmap：可以理解为 OKR 落实到当月的一个详细计划，更细的拆分任务以便合理的执行</p></li><li><p>GTD：对待办（TODO）分门别类的管理</p></li><li><p>会通过 Logseq 的 Query 进行搜集（按优先级、按 Tag、按关键字、按状态）</p></li></ul><p><img src="https://pic4.zhimg.com/80/v2-bb9523567c2e2804054f9f552d3051bf_1440w.webp" alt=""></p><ul><li>还可以配置到 Journey 的模板里，把重要事务钉在每天的首页上</li></ul><p><img src="https://pic3.zhimg.com/80/v2-125cdaa60f9d7dc17a4f99841d91786e_1440w.webp" alt=""></p><h3 id="笔记区" tabindex="-1">笔记区 <a class="header-anchor" href="#笔记区" aria-label="Permalink to &quot;笔记区&quot;">​</a></h3><ul><li><p><strong>核心</strong>：还是按 卡片笔记学习法 的方式，对需要被保留的笔记进行“管理”</p></li><li><p>Journey 无关紧要的草稿，可随意丢弃（未完成的 TODO 会被 GTD 采集，也无需关心）</p></li><li><p>Project/Books 虽然也是单独页面，但更像是一个分类标签来聚合一些内容</p></li><li><p>Note 永久笔记才是知识库的核心</p></li><li><p>记入“永久笔记”的笔记不代表就能真的永久的生效</p></li><li><p>第一，要有合适的组织方式，当然因为 Logseq 是大纲笔记，我会更偏向于使用树形的结构来组织页面内的笔记；当某一个页面的笔记过多时，可以考虑拆分段落（文档象限）或是拆分子页面（Hierarchy）</p></li><li><p>第二，“产生链接的知识才是有效的知识”，多脑补、多想象、多扩展，产生链接的知识会让你记的更深，并且还能产生跨领域的作用 —— e.g. “论敏捷项目管理在装修计划上的实践方案”</p></li></ul><p><img src="https://pic2.zhimg.com/80/v2-0657aa86ae9b1b880ef578bd69d24a5d_1440w.webp" alt=""></p><h3 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h3><ul><li>Github：作为备份仓库，当然也可以利用 Logseq export + Github pages 快速搭建一个博客网站，并且带双链、带图谱的酷炫网站</li><li>GoodNotes、棵岩阅读、微信读书、Apple Books：Logseq 虽然提供了内置的 PDF 阅读功能，但在阅读较长的书籍、英文的文献、需要做标记的 PPT，可能在 iPad + ApplePencil 的环境下会更方便快捷一些</li></ul><h2 id="输出-output" tabindex="-1">输出 Output <a class="header-anchor" href="#输出-output" aria-label="Permalink to &quot;输出 Output&quot;">​</a></h2><p><img src="https://pic1.zhimg.com/80/v2-84a9ff2439dac7d05696d5d7b426d95c_1440w.webp" alt=""></p><h3 id="方法论-2" tabindex="-1">方法论 <a class="header-anchor" href="#方法论-2" aria-label="Permalink to &quot;方法论&quot;">​</a></h3><ul><li>费曼学习法</li><li><a href="https://link.zhihu.com/?target=http%3A//www.zhoujingen.cn/" target="_blank" rel="noreferrer">敏捷个人</a></li><li>其他概念 ... （见图）</li></ul><h3 id="输出" tabindex="-1">输出 <a class="header-anchor" href="#输出" aria-label="Permalink to &quot;输出&quot;">​</a></h3><ul><li>获得反馈：输出会倒逼你重组知识结构。比“发布”更重要的是“收到反馈后修正模型”，这才是输入-输出闭环的核心。</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><blockquote><p>如果知识既不是被孤立地保存，也不是被孤立地学习，而是聚集在一个思想网络中，或者说是 “思维模型的网格” 中（M unger,1994），那么理解新的信息就变得更容易了。这不仅使学习和记忆变得更容易，而且提取信息及其可用之处变得更容易了。</p></blockquote><h3 id="只有个体能够构建网络-网络才能围绕个体构建" tabindex="-1"><strong>&quot;只有个体能够构建网络，网络才能围绕个体构建&quot;</strong> <a class="header-anchor" href="#只有个体能够构建网络-网络才能围绕个体构建" aria-label="Permalink to &quot;**&quot;只有个体能够构建网络，网络才能围绕个体构建&quot;**&quot;">​</a></h3><p><img src="https://pic4.zhimg.com/80/v2-a0fec4a76fb99fef7dbd5205d575839b_1440w.webp" alt="graph"></p>',38)])])}const b=e(o,[["render",r]]);export{d as __pageData,b as default};
